// App.js
import React, { useState } from 'react';
import { Grommet, Box, DataFilters, RangeInput } from 'grommet';
import { grommet } from 'grommet/themes';

const filterDefinitions = [
  { property: 'role', label: 'Role', options: ['Designer', 'Engineer'] },
  { property: 'status', label: 'Status', options: ['Offline', 'Online'] },
  { property: 'location', label: 'Location', options: ['Fort Collins, CO', 'San Jose, CA'] },
  {
    property: 'hoursAvailable', label: 'Remaining hours available',
    component: ({ value = [0, 40], onChange }) => (
      <Box pad={{ horizontal: 'small' }}>
        <RangeInput
          min={0} max={40} value={value}
          onChange={event => onChange([Number(event.target.value), value[1]])}
        />
      </Box>
    ),
  },
  { property: 'name', label: 'Name', options: [
      'Eric Soderberg', 'Taylor Seamans', 'Matthew Glissmann',
      'Greg Furuily', 'Vicky Avalos', 'Shimi Yacobi'
    ]
  },
];

export default function App() {
  const [filters, setFilters] = useState({});

  return (
    <Grommet theme={grommet} full>
      <Box pad="large" gap="medium">
        {/* Default Drop behavior: will overflow with many filters */}
        <DataFilters
          filters={filterDefinitions}
          values={filters}
          onChange={next => setFilters(next)}
          onApply={() => console.log('Applied filters:', filters)}
          onReset={() => setFilters({})}
        />

        {/* Using the new 'layer' prop: renders filters inside a full-page Layer */}
        <DataFilters
          drop
          layer
          filters={filterDefinitions}
          values={filters}
          onChange={next => setFilters(next)}
          onApply={() => console.log('Applied filters in layer:', filters)}
          onReset={() => setFilters({})}
        />
      </Box>
    </Grommet>
  );
}
